from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def feasible(T):
            rem = m
            pre = 0   # visits to current index already provided by bounces from the left
            for i in range(n):
                k = (T + points[i] - 1) // points[i] - pre   # visits still needed here
                if i == n - 1 and k <= 0:
                    break            # last index already satisfied, no extra arrival move
                if k < 1:
                    k = 1            # we still have to pass through index i once
                rem -= 2 * k - 1
                if rem < 0:
                    return False
                pre = k - 1
            return True

        lo, hi = 1, m * max(points)
        best = 0
        while lo <= hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                best = mid
                lo = mid + 1
            else:
                hi = mid - 1
        return best
